    :param spec: str, the 'min should match' specification as a string, which can include absolute numbers, percentages, and conditional expressions.
    :return: int, the calculated minimum number of clauses that must match according to the 'mm' spec.
    """

    def checked_parse_int(s: str) -> int:
        """Safely convert a string to an integer."""
        try:
            return int(s)
        except ValueError:
            raise ValueError(f"Invalid integer: {s}")

    spec = spec.strip()

    if '<' in spec:
        conditional_part, _ = spec.split('<', 1)
        if '%' in conditional_part:
            # Handle percentage-based conditional specs
            percentage = checked_parse_int(conditional_part.replace('%', ''))
            return min(num_clauses, num_clauses * (percentage / 100))
        else:
            # Handle absolute conditional specs
            return checked_parse_int(conditional_part)
    else:
        # Handle absolute and percentage-based specs
        if '%' in spec:
            # Handle percentage-based specs
            percentage = checked_parse_int(spec.replace('%', ''))
            return min(num_clauses, num_clauses * (percentage / 100))
        else:
            # Handle absolute specs
            return checked_parse_int(spec)
